inline const Entry *find(const std::string &name,const std::string &id,const std::string &mode) {
 const auto w=data().find(name); if(w==data().end()) return nullptr;
 const auto key=id+(mode=="grenade" ? ":grenade" : ""); const auto p=w->second.find(key);
 if(p!=w->second.end()) return &p->second; return &w->second.at("none"); }
inline bool supports(const std::string &name) { return data().find(name)!=data().end(); }
